mapper.update:
update official_event_party
set status=#{status}, organizer_authority=#{organizerAuthority}, status_by=#{operatorId}, status_at=now(), status_reason=#{reason}, update_time=now()
where id=#{id}

mapper.select:
select  from event_arrival_verification
where event_id=#{eventId} and mission_id=#{missionId} and member_id=#{memberId}
order by occurred_at desc,id desc limit 1
